def project_snapshot(row):
    row=deepcopy(row)
    if row['kind']=='after_VM_W32_initialization':row['registers']={}
    return row

def project_next_call(row):
    row=deepcopy(row);descriptor=bytes.fromhex(row.pop('descriptor_hex'))
    assert len(descriptor)==48 and raw_hash(descriptor)==row['descriptor_sha256']
    assert row['wrapper_offset']=='0x288540' and row['target_offset']=='0x26c9d0'
    assert int.from_bytes(descriptor[:8],'little')==IMAGE_BASE+0x26C9D0
    row['descriptor_width']=48;row['scope_object_address']=hex(int.from_bytes(descriptor[8:16],'little'))
    row['static_expected_target_arguments']={'x0':row['scope_object_address']}
    code=bytes.fromhex(row['wrapper_code_hex'])[:12]
    assert code.hex()=='012040a9e00308aa20001fd6'
    row['wrapper_code_hex']=code.hex();row['wrapper_code_sha256']=raw_hash(code)
    return row

def stop_boundary():
    return dict(kind='before_scope_leave_after_four_byte_allocation',stop_before=hex(VM_CALL),VM_call_executed=False,wrapper_executed=False,target_executed=False)

def active_regions(row,index):
    start=row['protection_activation']['initialized_allocation_from_index']
    return row['protected_ranges'][:-1] if start is not None and index<start else row['protected_ranges']

def validate_initialization(row,data,returned):
    assert INITIALIZATION_OBSERVED is True
    kinds=['allocation_VM_call','wrapper_entry','operator_new_entry','malloc_return','operator_new_return_before_store',
        'packed_result_stored','allocation_callback_return','after_VM_W32_initialization','before_next_VM_call']
    assert [x['kind'] for x in row['snapshots']]==kinds
    initialized,last=row['snapshots'][-2:];first=row['snapshots'][0];pointer=returned['allocation_address']
    assert initialized['pc']=='0x172090' and initialized['index']==585 and initialized['VM_cursor']=='0x10a284'
    assert initialized['registers']=={} and returned['index']<initialized['index']<last['index']
    assert row['protection_activation']==dict(retained_regions_from_index=1,initialized_allocation_from_index=initialized['index'])
    for x in row['snapshots'][:7]:assert x['allocation_initialized'] is False and 'initialized_word_is_one' not in x
    for x in (initialized,last):
        assert x['allocation_initialized'] is True and x['initialized_word_is_one'] is True and x['allocation_address']==pointer and x['allocation_width']==4
        assert x['allocation_sha256']==raw_hash((1).to_bytes(4,'little'))
    stores=[w for w in row['native_writes'] if w['address']==pointer]
    assert stores==[dict(index=initialized['index']-1,PC='main:0x17208c',address=pointer,size=4)]
    assert row['observation_sites'][initialized['index']-2]=='main:0x17208c'
    assert row['observed_code']['main:0x17208c']==data['static_code']['main:0x17208c']['hex']=='8b692ab8'
    before=first['scope_state']['diagnostic']
    assert row['protected_ranges'][-5:]==[
        dict(label='diagnostic_table',address=before['table'],size=0x800),dict(label='diagnostic_global_lock',address=before['global_lock'],size=48),
        dict(label='diagnostic_global_lock_pointer',address=hex(IMAGE_BASE+0x3DED98),size=8),dict(label='diagnostic_table_pointer',address=hex(IMAGE_BASE+0x3DEDA8),size=8),
        dict(label='initialized_allocation',address=pointer,size=4)]

def initialization_damage_cases():
    return [(('case_result','snapshots',-1,'initialized_word_is_one'),False),(('case_result','snapshots',-1,'allocation_initialized'),False),
        (('case_result','snapshots',-1,'allocation_sha256'),'0'*64),(('case_result','snapshots',-2,'registers'),{'x11':'0x1'}),
        (('case_result','protection_activation','initialized_allocation_from_index'),0)]

def validate_next_call(row,data,last):
    call=row['next_VM_call'];first=row['snapshots'][0]
    assert call['index']==row['instruction_observations'] and call['callsite_offset']==hex(VM_CALL) and call['VM_cursor_offset']==last['VM_cursor']=='0x10a29c'
    assert call['descriptor_width']==48 and call['descriptor_address']==last['registers']['x0']=='0x7004cd70'
    assert call['wrapper_offset']==hex(NEXT_WRAPPER)=='0x288540' and call['target_offset']==hex(NEXT_TARGET)=='0x26c9d0'
    assert call['scope_object_address']==first['scope_state']['scope_address']=='0x7004d1d8' and call['static_expected_target_arguments']=={'x0':call['scope_object_address']}
    assert call['wrapper_code_hex']==data['static_code']['main:'+hex(NEXT_WRAPPER)]['hex']
    assert len(bytes.fromhex(call['wrapper_code_hex']))==NEXT_WRAPPER_SIZE==12 and raw_hash(bytes.fromhex(call['wrapper_code_hex']))==call['wrapper_code_sha256']
    assert call['VM_call_executed'] is call['wrapper_executed'] is call['target_executed'] is False and 'descriptor_hex' not in call
    suffix=row['observation_sites'][row['snapshots'][6]['index']:]
    assert 'main:'+hex(NEXT_WRAPPER) not in suffix and 'main:'+hex(NEXT_TARGET) not in suffix

def compare_size_four(path,libc,base):
    pages,kw,_,pointer=controls.fixture(path,base,'size24');block=kw['argument_block_address'];controls.put(pages,block+8,4)
    result,watch,expected,steps=controls.original(path,libc,base,pages,kw,'size24',pointer);events=[]
    def allocate(tx,size):return controls.provider(block,'size24',pointer,events,lambda a,b:controls._write_span(tx,a,b))(size)
    own=controls.model.apply_request_287474_allocation_callback(pages,**kw,allocate=allocate)
    assert result==own==pointer and events==expected==[['malloc',4,pointer]]
    assert all(controls._read_span(pages,a,n)==data for (a,n),data in watch.items())
    print('PASS allocation',hex(base),'size4',steps,flush=True)
    return dict(image_base=hex(base),case='size4',native_instructions=steps,original_wrapper_and_operator_new_returned=True,
        declared_image_and_guest_bytes_equal=True,X64_size_and_result_store_equal=True,ordered_explicit_allocation_effects_equal=True,
        request_size_four_verified=True,component_malloc_provider_explicit=True,native_snapshot_input=False,physical_spills_and_PAC_compared=False)

class PostDiagnosticSmallAllocationScenario(previous.PostIdentifierHeapScopeScenario):
    def __init__(self,control):
        super().__init__(control)
        self._smallalloc_active=False;self._smallalloc_done=False;self._smallalloc_returned=False;self._smallalloc_stored=False
        self._smallalloc_count=0;self._smallalloc_trace=[];self._smallalloc_code={};self._smallalloc_rows=[];self._smallalloc_writes=[]
        self._smallalloc_services=[];self._smallalloc_live_writes=[];self._smallalloc_pointer=0;self._smallalloc_initialized=False;self._smallalloc_pending_store=False

    def _smallalloc_track(self,cpu,pc):
        self._smallalloc_count+=1;assert self._smallalloc_count<MAX_OBSERVATIONS
        domain,off=('libc',pc-LIBC_BASE) if LIBC_BASE<=pc<LIBC_BASE+0x200000 else ('main',pc-self.image)
        assert domain=='libc' or 0<=off<0x400000
        key=domain+':'+hex(off);self._smallalloc_trace.append(key);self._smallalloc_code[key]=bytes(cpu.mem_read(pc,4)).hex()

    def _smallalloc_scope_state(self,cpu,pc):
        count,rows=self._heapscope_count,self._heapscope_rows
        try:
            self._heapscope_count=self._smallalloc_count;self._heapscope_rows=[]
            self._heapscope_snapshot(cpu,pc,'retained_scope');row=self._heapscope_rows[0]
        finally:self._heapscope_count=count;self._heapscope_rows=rows
        return {k:v for k,v in row.items() if k not in SCOPE_EXCLUDED}

    def _smallalloc_snapshot(self,cpu,pc,kind):
        raw=bytes(cpu.mem_read(self._smallalloc_descriptor,48))
        row=dict(kind=kind,index=self._smallalloc_count,pc=hex(pc-self.image),SP=hex(cpu.reg_read(arm.UC_ARM64_REG_SP)),
            registers={f'x{n}':hex(self._reg(cpu,n)) for n in (0,30)},callee_saved_sha256=self._idctor_saved_hash(cpu),
            VM_state_address=hex(self._postalloc_vmstate),VM_cursor=hex(self._u(cpu,self._postalloc_vmstate)-self.image),
            descriptor_address=hex(self._smallalloc_descriptor),descriptor_sha256=raw_hash(raw),input_16_sha256=raw_hash(raw[:16]),tail_24_sha256=raw_hash(raw[24:]),
            result_slot_address=hex(self._smallalloc_descriptor+16),result_slot_sha256=raw_hash(raw[16:24]),result_store_completed=self._smallalloc_stored,
            scope_state=self._smallalloc_scope_state(cpu,pc),allocation_initialized=self._smallalloc_initialized)
