def read_static(path,libc):
    rows={}
    for domain,p in (('main',path),('libc',libc)):
        with p.open('rb') as f:
            elf=ELFFile(f)
            for off,size in CODE_RANGES[domain]:
                raw=previous.previous.elf_bytes(elf,f,off,size);rows[domain+':'+hex(off)]=dict(size=size,hex=raw.hex(),sha256=raw_hash(raw))
    return rows

def independent_controls(path,libc):
    cases=[controls.compare(path,libc,base,label) for base in controls.BASES for label in controls.PROFILES]
    cases.extend(compare_size_four(path,libc,base) for base in controls.BASES)
    guards=controls.guards(path)
    assert cases==CONTROL_SPECS and guards==ROLLBACK_SPECS
    return cases,guards

def run(path,libc):
    parent=prior_evidence();p=previous.previous.bootstrap.module_prefix();p.digest.verify_images(path,libc)
    code=read_static(path,libc);assert {k:v['sha256'] for k,v in code.items()}==CODE_SHA256
    def create(control):
        s=PostDiagnosticSmallAllocationScenario(control);s.path=path;s.continue_to_svc=True;return s
    rows=p.digest.context.replay(path,libc,case_controls=[p.CONTROL],_extension_factory=create,
        _request_profile=p.digest.previous.previous.name.previous.previous.PROFILE['name'],_handler_read_profile=p.digest.context.NULL_PAYLOAD_READ_PROFILE['name'])
    assert len(rows)==1
    cases,guards=independent_controls(path,libc)
    return dict(schema=SCHEMA,claims=claims_for(),providers=providers(),source_fingerprints=source_fingerprints(),input_provenance=provenance(parent),
        static_code=code,native_controls=cases,component_rollback_checks=guards,case_result=rows[0],case_result_sha256=digest(rows[0]))

def overlaps(address,size,region):
    a=int(address,16);b=int(region['address'],16);return a<b+region['size'] and b<a+size

def validate(data):
    parent=prior_evidence();old=parent['case_result']
    assert set(data)=={'schema','claims','providers','source_fingerprints','input_provenance','static_code','native_controls','component_rollback_checks','case_result','case_result_sha256'}
    assert data['schema']==SCHEMA and data['claims']==claims_for() and data['providers']==providers()
    assert data['source_fingerprints']==source_fingerprints() and data['input_provenance']==provenance(parent)
    assert data['native_controls']==CONTROL_SPECS and len(CONTROL_SPECS)==22
    assert data['component_rollback_checks']==ROLLBACK_SPECS and len(ROLLBACK_SPECS)==9
    assert set(data['static_code'])==set(CODE_SHA256)
    for domain,ranges in CODE_RANGES.items():
        assert len(ranges)==len({off for off,size in ranges})
        for off,size in ranges:
            entry=data['static_code'][domain+':'+hex(off)];raw=bytes.fromhex(entry['hex'])
            assert set(entry)=={'hex','size','sha256'} and len(raw)==entry['size']==size and raw_hash(raw)==entry['sha256']==CODE_SHA256[domain+':'+hex(off)]
    row=data['case_result'];assert data['case_result_sha256']==digest(row) and row['control']==old['control']
    assert set(row)=={'control','retained_diagnostic_entry','instruction_observations','instruction_trace_sha256','observed_code_sha256','snapshots',
        'native_writes','services','next_VM_call','observation_sites','observed_code','new_allocator_events','protected_ranges','protected_write_events',
        'protection_activation','stop_boundary'}|set(EXPECTED['ledgers'])
    assert row['retained_diagnostic_entry']==dict(case_result_sha256=digest(old),verified_fields=list(PARENT_FIELDS))
    sites=row['observation_sites'];code=row['observed_code'];h=hashlib.sha256()
    assert len(sites)==row['instruction_observations']==EXPECTED['instruction_observations']<MAX_OBSERVATIONS and set(sites)==set(code)
    assert sites[:6]==['main:'+hex(x) for x in (VM_CALL,WRAPPER,WRAPPER+4,WRAPPER+8,WRAPPER+12,TARGET)] and sites[-1]=='main:'+hex(VM_CALL)
    assert sites.count('main:'+hex(VM_CALL))==2 and sites.count('main:'+hex(VM_RESUME))==1 and sites.count('libc:'+hex(MALLOC))==1
    assert 'main:0x32a214' not in sites
    for key in sites:
        raw=bytes.fromhex(code[key]);assert len(raw)==4 and raw!=bytes.fromhex('010000d4');h.update(key.encode()+raw)
    assert h.hexdigest()==row['instruction_trace_sha256']==EXPECTED['instruction_trace_sha256'] and digest(code)==row['observed_code_sha256']==EXPECTED['observed_code_sha256']
    assert code['main:'+hex(VM_CALL)]=='00013fd6'
    for domain,ranges in CODE_RANGES.items():
        for off,size in ranges:
            raw=data['static_code'][domain+':'+hex(off)]['hex']
            for pc in range(off,off+size,4):
                if domain+':'+hex(pc) in code:assert code[domain+':'+hex(pc)]==raw[(pc-off)*2:(pc-off+4)*2]
    for key in ('snapshots','native_writes','services','next_VM_call','new_allocator_events','protected_ranges'):assert row[key]==EXPECTED[key],key
    snapshots=row['snapshots'];by_kind={x['kind']:x for x in snapshots};assert len(by_kind)==len(snapshots)
    first=snapshots[0];last=snapshots[-1];returned=by_kind['allocation_callback_return'];prior=old['snapshots'][-1]
    assert first['kind']=='allocation_VM_call' and last['kind']=='before_next_VM_call' and first['index']==1 and last['index']==len(sites)
    assert all(a['index']<b['index'] for a,b in zip(snapshots,snapshots[1:]))
    for x in snapshots:assert sites[x['index']-1]=='main:'+x['pc']
    assert first['descriptor_address']==old['next_VM_call']['descriptor_address'] and first['descriptor_sha256']==old['next_VM_call']['descriptor_sha256']
    assert first['result_slot_address']==old['next_VM_call']['result_slot_address'] and first['result_slot_sha256']==old['next_VM_call']['result_slot_before_sha256']
    assert first['VM_cursor']==returned['VM_cursor']==prior['VM_cursor']=='0x10a270'
    assert first['SP']==returned['SP']==prior['SP'] and first['callee_saved_sha256']==returned['callee_saved_sha256']==prior['callee_saved_sha256']
    expected_scope={k:v for k,v in prior.items() if k not in SCOPE_EXCLUDED}
    for x in snapshots:
        assert x['scope_state']==expected_scope and x['VM_state_address']==prior['VM_state_address']
        assert set(x['registers'])==(set() if x['kind']=='after_VM_W32_initialization' else {'x0','x30'})
        if x['index']<=returned['index']:assert x['input_16_sha256']==first['input_16_sha256'] and x['tail_24_sha256']==first['tail_24_sha256']
    assert expected_scope['diagnostic']['mutex_state_u16']==0x4001 and expected_scope['diagnostic']['owner_u32']==137
    assert expected_scope['scope_lock_result_i32']==0
    target=by_kind['operator_new_entry'];malloc=by_kind['malloc_return'];before=by_kind['operator_new_return_before_store'];stored=by_kind['packed_result_stored']
    assert target['registers']['x0']=='0x4' and by_kind['wrapper_entry']['registers']['x0']==first['descriptor_address']
    pointer=malloc['allocation_address'];assert int(pointer,16)!=0
    for x in (malloc,before,stored,returned):
        assert x['allocation_address']==pointer and x['allocation_width']==4 and x['registers']['x0']==pointer
        assert x['allocation_sha256']==malloc['allocation_sha256'] and x['allocation_initialized'] is False
    assert not before['result_store_completed'] and 'result_slot_pointer' not in before
    for x in (stored,returned):assert x['result_store_completed'] is True and x['result_slot_pointer']==pointer
    assert stored['result_slot_sha256']==raw_hash(int(pointer,16).to_bytes(8,'little'))
    assert [w for w in row['native_writes'] if w['PC']=='main:0x288518']==[dict(index=before['index'],PC='main:0x288518',address=first['result_slot_address'],size=8)]
    assert len(row['services'])==2
    for service,pc in zip(row['services'],('main:0x347fd0','libc:'+hex(MALLOC))):
        assert service['request']==4 and sites[service['index']-1]==pc and target['index']<service['index']<malloc['index']
    validate_initialization(row,data,returned)
    assert row['protected_ranges'][:len(old['protected_ranges'])]==old['protected_ranges'] and row['protected_write_events']==[]
    for w in row['native_writes']:
        assert set(w)=={'index','PC','address','size'} and sites[w['index']-1]==w['PC'] and w['size']>0
        regions=active_regions(row,w['index'])
        assert not any(overlaps(w['address'],w['size'],region) for region in regions)
    counts=deepcopy(old['allocator_counts']);counts['malloc']+=1
    for key,value in EXPECTED['ledgers'].items():assert row[key]==value==(counts if key=='allocator_counts' else old[key]),key
    assert row['new_allocator_events']==[['alloc',4,int(pointer,16),'0x32a210']]
    validate_next_call(row,data,last)
    assert row['stop_boundary']==stop_boundary()

def damaged_evidence_rejected(data):
    changes=[(('claims','next_VM_call_executed'),True),(('claims','complete_standalone_signer_verified'),True),
        (('claims','selected_mutex_unlock_executed'),True),(('claims','independent_owning_allocator_parity_verified'),True),
        (('providers','new_providers'),['hidden']),(('source_fingerprints','owners','allocation_model'),'0'*64),
        (('case_result','retained_diagnostic_entry','case_result_sha256'),'0'*64),(('case_result','instruction_observations'),0),
        (('case_result','instruction_trace_sha256'),'0'*64),(('case_result','observed_code_sha256'),'0'*64),
        (('case_result','snapshots',-1,'scope_state','counter_u32'),1),(('case_result','snapshots',-1,'scope_state','live_regions_sha256'),'0'*64),
        (('case_result','snapshots',-1,'scope_state','heap_string_payload_sha256'),'0'*64),(('case_result','snapshots',-1,'scope_state','cache_mutex_state_u16'),1),
        (('case_result','snapshots',6,'SP'),'0x0'),(('case_result','snapshots',6,'callee_saved_sha256'),'0'*64),
        (('case_result','snapshots',-1,'scope_state','diagnostic','mutex_state_u16'),0x4000),(('case_result','snapshots',-1,'scope_state','diagnostic','owner_u32'),0),
        (('case_result','snapshots',-1,'scope_state','diagnostic','table_sha256'),'0'*64),
        (('case_result','snapshots',-1,'scope_state','prior_identifier_entry','entry_sha256'),'0'*64),
        (('case_result','snapshots',5,'result_slot_pointer'),'0x0'),(('case_result','snapshots',5,'result_store_completed'),False),
        (('case_result','snapshots',3,'allocation_address'),'0x0'),(('case_result','snapshots',3,'allocation_sha256'),'0'*64),
        (('case_result','services',0,'request'),0),(('case_result','native_writes',0,'size'),99),
        (('case_result','next_VM_call','target_offset'),'0x0'),(('case_result','next_VM_call','descriptor_sha256'),'0'*64),
        (('case_result','next_VM_call','wrapper_code_sha256'),'0'*64),(('case_result','next_VM_call','target_executed'),True),
        (('case_result','next_VM_call','descriptor_hex'),'omitted'),(('case_result','new_allocator_events'),[]),
        (('case_result','protected_write_events'),['hidden']),(('case_result','stop_boundary','VM_call_executed'),True),
        (('case_result','raw_identifier'),'omitted'),(('case_result','raw_allocation'),'omitted'),(('raw_identifier',),'omitted'),
        (('native_controls',0,'native_snapshot_input'),True),(('component_rollback_checks',0,'all_pages_unchanged'),False)]
    changes.extend(initialization_damage_cases())
    for key in EXPECTED['ledgers']:changes.append((('case_result',key),{}))
    for key in CODE_SHA256:changes.append((('static_code',key,'sha256'),'0'*64))
    for path,value in changes:
        bad=deepcopy(data);obj=bad
        for key in path[:-1]:obj=obj[key]
        obj[path[-1]]=value
        if path[0]=='case_result':bad['case_result_sha256']=digest(bad['case_result'])
        try:validate(bad)
        except (AssertionError,KeyError,ValueError,TypeError):continue
        raise AssertionError(f'damaged post-scope allocation evidence accepted: {path}')
    return len(changes)

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--elf',type=Path);parser.add_argument('--libc',type=Path)
    mode=parser.add_mutually_exclusive_group();mode.add_argument('--capture',action='store_true');mode.add_argument('--replay',action='store_true')
    args=parser.parse_args()
    if (args.capture or args.replay) and (not args.elf or not args.libc):parser.error('--capture and --replay require --elf and --libc')
    if args.capture:
        if EVIDENCE.exists():raise FileExistsError('frozen evidence already exists; refusing overwrite')
        data=run(args.elf,args.libc);validate(data);rejected=damaged_evidence_rejected(data)
        with EVIDENCE.open('x',encoding='utf-8',newline='\n') as out:out.write(json.dumps(data,indent=2)+'\n')
    else:
        data=json.loads(EVIDENCE.read_text(encoding='utf-8'));validate(data);rejected=damaged_evidence_rejected(data)
        if args.replay:assert run(args.elf,args.libc)==data,'fresh post-scope allocation replay differs'
    print(json.dumps(dict(schema=SCHEMA,native_controls=len(data['native_controls']),component_rollback_checks=len(data['component_rollback_checks']),
        damaged_evidence_rejected=rejected,instruction_observations=data['case_result']['instruction_observations'],
        original_four_byte_allocation_returned=True,selected_mutex_held_at_stop=True,VM_W32_initialization_observed=INITIALIZATION_OBSERVED,
        next_VM_call_executed=False,complete_standalone_signer_verified=False)))
if __name__=='__main__':main()
